import { ArrowRightIcon, CheckIcon } from "lucide-react"
import { useRef, type ReactNode } from "react"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { ChatComposer } from "@/components/ChatComposer"
import { PREMIUM_FEATURES, type PremiumFeatureId, type PremiumFeatureInfo } from "@/lib/premium-features"
import { cn } from "@/lib/utils"
import { openLicenseUpgrade } from "@/lib/license-upgrade-navigation"

type Props = {
  feature?: PremiumFeatureId
  /** Text fallback for extension-provided features outside the built-in catalog. */
  title?: string
  description?: string
  disabledInputPlaceholder?: string
  compact?: boolean
  className?: string
}

export function PremiumBadge({ className }: { className?: string }) {
  return <span className={cn("shrink-0 rounded bg-muted px-1.5 py-0.5 text-[10px] font-normal text-muted-foreground", className)}>Premium</span>
}

function FeatureDetails({ info, footerStart, onUpgrade }: { info: PremiumFeatureInfo; footerStart?: ReactNode; onUpgrade?: () => void }) {
  return <>
    <DialogHeader>
      <div><PremiumBadge /></div>
      <DialogTitle>{info.title}</DialogTitle>
      <DialogDescription>{info.description}</DialogDescription>
    </DialogHeader>
    {info.benefits.length ? (
      <ul className="space-y-2 text-sm">
        {info.benefits.map(benefit => <li key={benefit} className="flex items-start gap-2">
          <CheckIcon className="mt-0.5 size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
          <span>{benefit}</span>
        </li>)}
      </ul>
    ) : null}
    <DialogFooter>
      {footerStart}
      <DialogClose asChild><Button size="sm" onClick={() => { onUpgrade?.(); openLicenseUpgrade() }}>Upgrade <ArrowRightIcon /></Button></DialogClose>
    </DialogFooter>
  </>
}

function FeatureModalContent({ info }: { info: PremiumFeatureInfo }) {
  const upgrading = useRef(false)
  return <DialogContent className="max-h-[calc(100dvh-2rem)] overflow-y-auto sm:max-w-md" onCloseAutoFocus={event => { if (upgrading.current) event.preventDefault() }}>
    <FeatureDetails info={info} onUpgrade={() => { upgrading.current = true }} />
  </DialogContent>
}

/** Render directly in an existing Dialog (Library) without nesting another modal. */
export function ProductFeatureDetails({ feature, onBack, onUpgrade }: { feature: PremiumFeatureId; onBack?: () => void; onUpgrade?: () => void }) {
  return <FeatureDetails info={PREMIUM_FEATURES[feature]} onUpgrade={onUpgrade} footerStart={onBack ? <Button size="sm" variant="outline" onClick={onBack}>Back</Button> : undefined} />
}

export function ProductFeatureDialog({ feature, open, onOpenChange }: {
  feature: PremiumFeatureId
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  return <Dialog open={open} onOpenChange={onOpenChange}>
    <FeatureModalContent info={PREMIUM_FEATURES[feature]} />
  </Dialog>
}

export function PremiumFeaturePlaceholder({ feature, title, description, disabledInputPlaceholder, compact = false, className }: Props) {
  const info: PremiumFeatureInfo = feature ? PREMIUM_FEATURES[feature] : {
    title: title ?? "Premium feature",
    summary: description ?? "Explore more ways to customize your map.",
    description: description ?? "Explore more ways to customize your map.",
    benefits: [],
  }
  return (
    <div className={cn("relative flex min-h-0 flex-col", !compact && "h-full", className)}
      data-premium-feature data-ai-chat-overlay={disabledInputPlaceholder ? "" : undefined}>
      <div className={cn("flex min-h-0 items-center justify-center p-3", !compact && "flex-1 overflow-auto")}>
        <div className="max-w-xs space-y-3 text-center">
          <div className="flex flex-wrap items-center justify-center gap-2 text-xs font-medium">
            <span>{info.title}</span><PremiumBadge />
          </div>
          <p className="text-xs leading-relaxed text-muted-foreground">{info.summary}</p>
          <Dialog>
            <DialogTrigger asChild><Button size="xs" variant="outline">Learn more</Button></DialogTrigger>
            <FeatureModalContent info={info} />
          </Dialog>
        </div>
      </div>
      {disabledInputPlaceholder ? <ChatComposer placeholder={disabledInputPlaceholder} disabled /> : null}
    </div>
  )
}

export function ProductFeaturePlaceholder({ feature, compact = false }: { feature: PremiumFeatureId; compact?: boolean }) {
  return <PremiumFeaturePlaceholder feature={feature} compact={compact} />
}

/** Lite owns discoverability; paid modules own the actual settings and implementation. */
export function PremiumFeatureButton({ feature }: { feature: PremiumFeatureId }) {
  return <Dialog>
    <DialogTrigger asChild>
      <button type="button" className="flex w-full items-center justify-between gap-2 py-1 text-left text-xs text-muted-foreground hover:text-foreground">
        <span>{PREMIUM_FEATURES[feature].title}</span><PremiumBadge />
      </button>
    </DialogTrigger>
    <FeatureModalContent info={PREMIUM_FEATURES[feature]} />
  </Dialog>
}
